import {
  MicroVerticalBuildMarkerSchema,
  MicroVerticalReadinessSchema,
  createMicroVerticalOperationContext,
} from '@historical-app/shared-contracts/microvertical-api-baseline';
import type {
  MicroVerticalBuildMarker,
  MicroVerticalReadiness,
  MicroVerticalOperationContext,
} from '@historical-app/shared-contracts/microvertical-api-baseline';
import {
  HttpApi,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  Schema,
} from '@modern-js/plugin-bff/effect-client';

export type OrdersMarker = MicroVerticalBuildMarker;

export interface OrdersItem {
  readonly id: string;
  readonly marker: OrdersMarker;
  readonly title: string;
}

export type OrdersReadiness = MicroVerticalReadiness;

export interface OrdersCreatePayload {
  readonly title: string;
}

export interface OrdersListResponse {
  readonly items: readonly OrdersItem[];
}

export interface OrdersCreateResponse {
  readonly item: OrdersItem;
}

export interface OrdersNotFound {
  readonly _tag: 'OrdersNotFound';
  readonly id: string;
}

export const ordersMarkerSchema: Schema.Codec<OrdersMarker> =
  MicroVerticalBuildMarkerSchema;

export const ordersItemSchema: Schema.Codec<OrdersItem> = Schema.Struct({
  id: Schema.String,
  marker: ordersMarkerSchema,
  title: Schema.String,
});

export const ordersReadinessSchema: Schema.Codec<OrdersReadiness> =
  MicroVerticalReadinessSchema;

export const ordersCreatePayloadSchema: Schema.Codec<OrdersCreatePayload> =
  Schema.Struct({
    title: Schema.String,
  });

export const ordersNotFoundSchema: Schema.Codec<OrdersNotFound> =
  Schema.TaggedStruct('OrdersNotFound', {
    id: Schema.String,
  }).pipe(HttpApiSchema.status(404));

export type OperationContext = MicroVerticalOperationContext;

export const ordersFoundationApi = HttpApi.make('OrdersApiFoundation').add(
  HttpApiGroup.make('foundation').add(
    HttpApiEndpoint.get('readiness', '/orders/readiness', {
      success: ordersReadinessSchema,
    })
  )
);
export const ordersApi = HttpApi.make('OrdersApi')
  .addHttpApi(ordersFoundationApi)
  .add(
    HttpApiGroup.make('orders')
      .add(
        HttpApiEndpoint.get('list', '/orders', {
          query: {
            limit: Schema.optional(Schema.FiniteFromString),
          },
          success: Schema.Struct({
            items: Schema.Array(ordersItemSchema),
          }),
        })
      )

      .add(
        HttpApiEndpoint.get('get', '/orders/:id', {
          error: ordersNotFoundSchema,
          params: {
            id: Schema.String,
          },
          success: ordersItemSchema,
        })
      )
      .add(
        HttpApiEndpoint.post('create', '/orders', {
          payload: ordersCreatePayloadSchema,
          success: Schema.Struct({
            item: ordersItemSchema,
          }),
        })
      )
  );

export const ordersOperationContexts = {
  create: createMicroVerticalOperationContext({
    method: 'POST',
    operationId: 'OrdersApi:orders:create',
    routePath: '/orders',
  }),
  get: createMicroVerticalOperationContext({
    method: 'GET',
    operationId: 'OrdersApi:orders:get',
    routePath: '/orders/:id',
  }),
  list: createMicroVerticalOperationContext({
    method: 'GET',
    operationId: 'OrdersApi:orders:list',
    routePath: '/orders',
  }),
  readiness: createMicroVerticalOperationContext({
    method: 'GET',
    operationId: 'OrdersApi:orders:readiness',
    routePath: '/orders/readiness',
  }),
} satisfies Record<string, OperationContext>;

export const ordersApiContract = {
  apiPrefix: '/orders-api',
  basePath: '/orders-api/orders',
  ownerId: 'orders',
  readinessPath: '/orders-api/orders/readiness',
} as const;

import { useDistributedSsrFragmentProps } from '@modern-js/runtime/module-federation/distributed-ssr';
import type { ComponentProps } from 'react';

import Widget from '../../../../../components/orders-widget';

export default function WidgetFragmentPage() {
  const props = useDistributedSsrFragmentProps<ComponentProps<typeof Widget>>({
    boundaryId: 'verticalOrders',
    expose: './Widget',
  });

  return (
    <>
      <template
        data-modern-boundary-id="verticalOrders"
